}

header {
  margin-bottom: 30px;
  text-align: center;
}

h1 {
  font-size: 28px;
  color: #1a202c;
  margin-bottom: 12px;
  font-weight: 700;
}

header p {
  color: #718096;
  font-size: 14px;
  line-height: 1.6;
}

form {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.form-field {
  display: flex;
  flex-direction: column;
