  header p {
    font-size: 13px;
  }

  form {
    gap: 18px;
  }

  input[type="text"],
  input[type="email"],
  input[type="tel"] {
    font-size: 16px;
  }
}

/* High contrast mode support */
@media (prefers-contrast: more) {
  input[aria-invalid="true"] {
