    border-color: CanvasText;
    background-color: Canvas;
    color: CanvasText;
  }

  input[aria-invalid="true"] {
    border-color: Mark;
    background-color: Canvas;
  }

  .submit-button {
    border: 2px solid CanvasText;
    background: Canvas;
    color: CanvasText;
  }

  .submit-button:focus {
    outline: 2px solid CanvasText;
  }
}
